import {days,meals,menu,highlights,indiaNow,dayIndex,schedule,isNonVeg,nextBiryani} from './menu.js';
const $=id=>document.getElementById(id),icons=['☀','◒','♧','☾'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let now=indiaNow(),selectedDay=dayIndex(now),selectedMeal=0,weekOffset=0,view='today',query='',toastTimer;
let favourites=new Set(),veg=false;
try{const saved=JSON.parse(localStorage.getItem('messmate:favourites:v3')||'[]');if(Array.isArray(saved))favourites=new Set(saved.filter(x=>typeof x==='string'));veg=localStorage.getItem('messmate:veg:v3')==='true';}catch{}
const minutes=()=>now.getHours()*60+now.getMinutes();
const time=n=>`${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n<720?'AM':'PM'}`;
const range=(day,meal)=>schedule(day)[meal].map(time).join(' – ');
function current(){return schedule(dayIndex(now)).findIndex(([a,b])=>minutes()>=a&&minutes()<b);}
function upcoming(){const c=current();if(c>=0)return{day:dayIndex(now),meal:c,live:true,tomorrow:false};const m=schedule(dayIndex(now)).findIndex(([s])=>s>minutes());return m>=0?{day:dayIndex(now),meal:m,live:false,tomorrow:false}:{day:(dayIndex(now)+1)%7,meal:0,live:false,tomorrow:true};}
selectedMeal=upcoming().meal;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2400);}
function save(){try{localStorage.setItem('messmate:favourites:v3',JSON.stringify([...favourites]));localStorage.setItem('messmate:veg:v3',String(veg));}catch{toast('Saved for this visit. Browser storage is unavailable.');}}
function dish(item){return `<div class="dish"><span class="dish-type ${isNonVeg(item)?'nonveg':''}" aria-label="${isNonVeg(item)?'Contains meat or egg':'Vegetarian item'}">●</span><span class="dish-name">${esc(item)}</span><button class="heart ${favourites.has(item)?'saved':''}" data-save="${esc(item)}" aria-label="${favourites.has(item)?'Remove':'Save'} ${esc(item)} ${favourites.has(item)?'from':'to'} favourites" aria-pressed="${favourites.has(item)}">${favourites.has(item)?'♥':'♡'}</button></div>`;}
function renderHero(){const u=upcoming();$('hero-status').textContent=u.live?'On the schedule · now':u.tomorrow?'Tomorrow’s first good thing':'Your next food break';$('hero-kicker').textContent=`${u.tomorrow?'Tomorrow · ':''}${meals[u.meal]} at your mess`;$('hero-title').textContent=highlights[u.day][u.meal];$('hero-sub').textContent=['A fresh start, a warm plate. Make time for the most delicious part of your morning.','Your midday pause, sorted. A little comfort before the rest of your day.','Close the laptop. Catch up with your people over a well-earned little break.','Long day? There’s a warm plate waiting. Finish the day on a good note.'][u.meal];$('hero-time').textContent=range(u.day,u.meal);}
function renderClock(){const c=current(),u=upcoming(),d=dayIndex(now);$('food-clock').innerHTML=meals.map((name,i)=>{const ended=minutes()>=schedule(d)[i][1];return `<button class="clock-row ${i===c?'current':''} ${i===u.meal&&!u.tomorrow?'upcoming':''}" data-clock="${i}" aria-label="View today's ${name}"><span class="meal-symbol">${icons[i]}</span><span class="clock-info"><strong>${name}</strong><small>${range(d,i)}</small></span><span class="clock-state">${i===c?'Scheduled now':ended?'Finished':i===u.meal?'Up next':'Later'}</span></button>`;}).join('');$('clock-time').textContent=time(minutes());}
function renderDays(){const monday=new Date(now);monday.setDate(now.getDate()-dayIndex(now)+weekOffset);$('days').innerHTML=days.map((day,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);return `<button class="day-button ${i===selectedDay?'active':''} ${i===dayIndex(now)&&weekOffset===0?'today':''}" data-day="${i}" aria-label="${day}, ${d.toLocaleDateString('en-GB',{day:'numeric',month:'long'})}" aria-pressed="${i===selectedDay}"><span>${day.slice(0,3)}</span><strong>${d.getDate()}</strong></button>`;}).join('');}
function renderMeal(){renderDays();$('meal-tabs').innerHTML=meals.map((name,i)=>`<button class="meal-tab ${i===selectedMeal?'active':''}" data-meal="${i}" aria-pressed="${i===selectedMeal}"><span aria-hidden="true">${icons[i]}</span>${name}</button>`).join('');$('meal-heading').textContent=`${days[selectedDay]}’s ${meals[selectedMeal].toLowerCase()}`;$('meal-timing').textContent=range(selectedDay,selectedMeal)+' · Campus time';$('veg-toggle').setAttribute('aria-pressed',String(veg));$('meal-items').innerHTML=menu[selectedDay][selectedMeal].filter(item=>!veg||!isNonVeg(item)).map(dish).join('');}
function highlight(s){if(!query)return esc(s);const start=s.toLowerCase().indexOf(query.toLowerCase());if(start<0)return esc(s);return esc(s.slice(0,start))+'<mark>'+esc(s.slice(start,start+query.length))+'</mark>'+esc(s.slice(start+query.length));}
function renderWeek(){let count=0;$('week-veg').setAttribute('aria-pressed',String(veg));$('week-grid').innerHTML=days.map((day,d)=>{const entries=meals.map((meal,m)=>{const all=menu[d][m].filter(x=>!veg||!isNonVeg(x));const relevant=!query||day.toLowerCase().includes(query.toLowerCase())||meal.toLowerCase().includes(query.toLowerCase())||all.some(x=>x.toLowerCase().includes(query.toLowerCase()));if(!relevant)return '';count++;return `<section class="week-meal"><h3>${icons[m]} ${meal}<button data-open="${d},${m}" aria-label="View ${day} ${meal}">View meal ↗</button></h3><p>${all.map(highlight).join(' · ')}</p></section>`;}).join('');return entries?`<article class="week-card"><header><h2>${highlight(day)}</h2><span>${d===dayIndex(now)?'TODAY':'4 daily breaks'}</span></header>${entries}</article>`:'';}).join('');if(!count)$('week-grid').innerHTML='<div class="empty"><span>⌕</span><h2>Nothing on the menu… yet.</h2><p>Try a dish like “paneer”, a meal like “lunch”, or a day.</p><button class="outline-button" id="clear-search">Clear search</button></div>';}
function renderSaved(){$('saved-count').textContent=`${favourites.size} saved`;if(!favourites.size){$('saved-grid').innerHTML='<div class="empty"><span>♡</span><h2>Good taste starts here.</h2><p>Heart the dishes you love.<br>Find them here, along with when they’re on the menu.</p><button data-view="today" class="lime-button">Find your favourites ↗</button></div>';return;}$('saved-grid').innerHTML=[...favourites].map(item=>{const matches=[];menu.forEach((day,d)=>day.forEach((list,m)=>{if(list.includes(item))matches.push(`${days[d].slice(0,3)} ${meals[m].toLowerCase()}`);}));return `<article class="saved-card">${dish(item)}<p>${matches.map(esc).join(' · ')}</p></article>`;}).join('');}
function setView(next,{scroll=true}={}){view=['today','week','saved'].includes(next)?next:'today';for(const v of ['today','week','saved'])$(v+'-view').hidden=v!==view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.closest('nav')){if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}});$('page-title').innerHTML={today:'Your day, <em>served.</em>',week:'A week of <em>good food.</em>',saved:'Your kind of <em>comfort.</em>'}[view];$('intro-copy').textContent={today:'Less “what’s in the mess?” More enjoying your day.',week:'Seven days. Four meals. Something to look forward to.',saved:'All your favourites. Always close to heart.'}[view];if(view==='week')renderWeek();if(view==='saved')renderSaved();history.replaceState(null,'','#'+view);if(scroll)window.scrollTo({top:0,behavior:'smooth'});}
function reset(){now=indiaNow();selectedDay=dayIndex(now);weekOffset=0;selectedMeal=upcoming().meal;renderMeal();setView('today');}
function info(){$('info-dialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){setView(b.dataset.view);return;}if(b.dataset.save){const item=b.dataset.save,exists=favourites.has(item);exists?favourites.delete(item):favourites.add(item);save();renderMeal();if(view==='saved')renderSaved();toast(exists?'Removed from your favourites':'A good choice. Saved to favourites ♡');return;}if(b.dataset.day!==undefined){selectedDay=+b.dataset.day;renderMeal();}if(b.dataset.meal!==undefined){selectedMeal=+b.dataset.meal;renderMeal();}if(b.dataset.clock!==undefined){selectedDay=dayIndex(now);weekOffset=0;selectedMeal=+b.dataset.clock;renderMeal();$('menu-section').scrollIntoView({behavior:'smooth'});}if(b.dataset.open){[selectedDay,selectedMeal]=b.dataset.open.split(',').map(Number);weekOffset=0;setView('today',{scroll:false});renderMeal();$('menu-section').scrollIntoView({behavior:'smooth'});}if(b.id==='clear-search'){query='';$('search').value='';renderWeek();}});
$('jump-menu').onclick=()=>{const u=upcoming();selectedDay=u.day;weekOffset=u.tomorrow&&u.day===0?7:0;selectedMeal=u.meal;renderMeal();$('menu-section').scrollIntoView({behavior:'smooth'});};$('reset-today').onclick=reset;
for(const id of ['veg-toggle','week-veg'])$(id).onclick=()=>{veg=!veg;save();renderMeal();renderWeek();};
$('search').addEventListener('input',e=>{query=e.target.value.trim();renderWeek();});
for(const id of ['about','campus','mobile-info','biryani'])$(id).onclick=info;
$('info-dialog').querySelector('.close-dialog').onclick=()=>$('info-dialog').close();
$('info-dialog').addEventListener('click',e=>{if(e.target===$('info-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function renderDate(){$('today-date').textContent=now.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('biryani-date').textContent='Next up · '+nextBiryani(now).toLocaleDateString('en-GB',{day:'numeric',month:'short'});}
renderDate();renderHero();renderClock();renderMeal();setView(location.hash.slice(1)||'today',{scroll:false});
setInterval(()=>{const old=dayIndex(now);now=indiaNow();renderDate();renderHero();renderClock();if(old!==dayIndex(now))renderDays();},30000);
window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
